
'use strict';
const KEY='fisio-prototype-v1';let db={version:1,patients:[],sessions:[]},view='home',selected=null,editing=null,editable=false,anchor=new Date();
const app=document.getElementById('app');const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const id=()=>crypto.randomUUID();const money=n=>Number(n||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});const day=d=>{let x=new Date(d);return `${x.getFullYear()}-${String(x.getMonth()+1).padStart(2,'0')}-${String(x.getDate()).padStart(2,'0')}`};const date=s=>new Date(s+'T12:00:00').toLocaleDateString('pt-BR');const patient=s=>db.patients.find(p=>p.id===s.patientId);const say=s=>document.getElementById('msg').textContent=s;
try{const raw=localStorage.getItem(KEY);if(raw){const saved=JSON.parse(raw);if(saved.version!==1||!Array.isArray(saved.patients)||!Array.isArray(saved.sessions))throw Error();db=saved}}catch{say('Não foi possível ler os dados. Não grave alterações antes de recuperar seu backup.')}
function persist(next){try{localStorage.setItem(KEY,JSON.stringify(next));db=next;return true}catch{say('Falha ao salvar. Exporte um backup antes de fechar.');return false}}
function commit(fn){const next=structuredClone(db);fn(next);if(persist(next)){say('Salvo neste navegador.');render()}}
function field(label,name,value='',type='text',attrs=''){return `<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${attrs}></label>`}
function options(values,current){return values.map(v=>`<option ${v===current?'selected':''}>${esc(v)}</option>`).join('')}
function pSelect(current){return `<label>Paciente<select name="patientId" required><option value="">Selecione</option>${db.patients.map(p=>`<option value="${p.id}" ${p.id===current?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label>`}
function navigate(v){view=v;editing=null;editable=false;selected=v==='patients'?'':null;say('');render()}
function render(){document.querySelector('nav').hidden=view==='home';if(view==='home')home();if(view==='agenda')agenda();if(view==='patients')patients();if(view==='finance')finance();if(view==='records')records();if(view==='clinical')clinical();if(view==='backup')backup();if(editing!==null){const form=document.getElementById('sessionForm');if(form){const fields=form.querySelector('fieldset');if(fields)fields.disabled=!!editing&&!editable;}}}
const tileIcons={agenda:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 11h18M8 15h2m4 0h2M8 18h2"/>',patients:'<circle cx="10" cy="7" r="4"/><path d="M3 21v-2a7 7 0 0 1 12-5M19 13v8M15 17h8"/>',finance:'<rect x="2" y="5" width="20" height="14" rx="2"/><circle cx="12" cy="12" r="3"/><path d="M5 9v6M19 9v6"/>',records:'<rect x="5" y="4" width="14" height="17" rx="2"/><path d="M9 4V2h6v2M9 10h6M9 14h6M9 18h4"/>'};

function createPatientPDF(p,rows){
 const {jsPDF}=globalThis.jspdf;const pdf=new jsPDF({unit:'mm',format:'a4'});const margin=18,width=174,bottom=274;let y=43;
 pdf.setProperties({title:'Registros de atendimentos - '+p.name,author:'Geovane M. da Silva',subject:'Avaliação, evolução e atividades realizadas'});
 function header(){pdf.setFillColor(16,64,49);pdf.rect(0,0,210,34,'F');pdf.setTextColor(247,247,247);pdf.setFont('helvetica','bold');pdf.setFontSize(14);pdf.text('GEOVANE M. DA SILVA',margin,13);pdf.setFont('helvetica','normal');pdf.setFontSize(9);pdf.text('Crefito: 549225-F',margin,20);pdf.setFontSize(10);pdf.text('Fisioterapia | Registros de atendimentos',margin,27);pdf.setTextColor(16,64,49)}
 function next(){pdf.addPage();header();y=43}
 function space(h){if(y+h>bottom)next()}
 function text(value,size=10,bold=false){pdf.setFont('helvetica',bold?'bold':'normal');pdf.setFontSize(size);const lines=pdf.splitTextToSize(String(value||'Não registrado.').replace(/\r\n/g,'\n'),width);const step=size*0.3528*1.45;for(const line of lines){space(step);pdf.text(line,margin,y);y+=step}y+=3}
 function section(title,value){space(18);text(title,10,true);text(value,10,false);y+=2}
 header();text('Paciente: '+p.name,12,true);if(p.birth)text('Nascimento: '+date(p.birth),9);text('Emitido em: '+new Date().toLocaleString('pt-BR'),9);text('Atendimentos realizados: '+rows.length,9);y+=3;
 for(const s of [...rows].sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time))){space(30);pdf.setDrawColor(165,137,79);pdf.line(margin,y-2,192,y-2);y+=5;text(date(s.date)+' - '+s.time+' | '+(s.type||''),12,true);if(s.audit?.length){const last=s.audit[s.audit.length-1];text('Registro editado em: '+new Date(last.at).toLocaleString('pt-BR'),9);text('Motivo: '+last.reason,9)}section('Observações da avaliação',s.assessment);section('Evolução do atendimento',s.evolution);section('Atividades realizadas',s.activities);y+=6}
 const total=pdf.getNumberOfPages();for(let i=1;i<=total;i++){pdf.setPage(i);pdf.setDrawColor(224,204,173);pdf.line(margin,281,192,281);pdf.setFont('helvetica','normal');pdf.setFontSize(8);pdf.setTextColor(100,110,104);pdf.text('Registro clínico - uso confidencial',margin,287);pdf.text('Página '+i+' de '+total,192,287,{align:'right'})}return pdf
}
function home(){const tiles=[['agenda','AGENDA','Horários, agendamentos e retornos'],['patients','CADASTRAR PACIENTE','Dados pessoais e cadastros'],['finance','FINANCEIRO','Pagamentos, pendências e notas'],['records','ATENDIMENTOS REALIZADOS','Avaliações, evoluções e atividades']];app.innerHTML=`<div class="welcome"><h2>Seu espaço de trabalho</h2><p>Selecione uma área para começar.</p></div><div class="home-grid">${tiles.map(([key,title,description])=>`<button class="home-button" data-view="${key}"><span class="tile-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${tileIcons[key]}</svg></span><span><span class="tile-title">${title}</span><span class="tile-description">${description}</span></span></button>`).join('')}</div><p class="home-footer">Geovane M. da Silva · Fisioterapia · Protótipo 0.9</p>`}
function clinical(){app.innerHTML='<div class="card"><h2>Avaliação e evolução</h2><p class="muted">Registre a avaliação, evolução e atividades. O atendimento será marcado como realizado ao salvar.</p></div>'+sessionForm()}
function records(){app.innerHTML=`<div class="card"><h2>Atendimentos realizados</h2><input id="recordSearch" placeholder="Buscar paciente"><div id="recordList"></div></div>${editing!==null?sessionForm():''}`;const list=()=>{const q=document.getElementById('recordSearch').value.toLocaleLowerCase();document.getElementById('recordList').innerHTML=sessionRows(db.sessions.filter(s=>s.status==='Realizado'&&(patient(s)?.name||'').toLocaleLowerCase().includes(q)))};list();document.getElementById('recordSearch').oninput=list;}
document.querySelector('nav').onclick=e=>{if(e.target.dataset.view)navigate(e.target.dataset.view)};
function agenda(){let start=new Date(anchor);start.setDate(start.getDate()-((start.getDay()+6)%7));const days=Array.from({length:7},(_,i)=>{let d=new Date(start);d.setDate(d.getDate()+i);return day(d)});app.innerHTML=`<div class="card"><div class="row"><h2 style="margin:0;flex:1">Agenda semanal</h2><button data-action="prev" class="secondary">← Semana</button><button data-action="today" class="secondary">Hoje</button><button data-action="next" class="secondary">Semana →</button><button data-action="new">+ Agendar</button></div><p class="muted">${date(days[0])} a ${date(days[6])} · Agenda local, sem consulta à disponibilidade compartilhada.</p><div class="scroll"><div class="week">${days.map(d=>`<div class="day" data-day="${d}" tabindex="0" aria-label="Agendar em ${date(d)}"><strong>${new Date(d+'T12:00').toLocaleDateString('pt-BR',{weekday:'short',day:'2-digit'})}</strong><span class="day-hint">Clique para agendar</span>${db.sessions.filter(s=>s.date===d).sort((a,b)=>a.time.localeCompare(b.time)).map(s=>`<button class="event" data-session="${s.id}"><strong>${s.time} · ${esc(patient(s)?.name||'Paciente')}</strong><br>${esc(s.type)} · ${esc(s.status)}</button>`).join('')}</div>`).join('')}</div></div>${editing!==null?sessionForm():''}`}
function sessionForm(){const s=db.sessions.find(x=>x.id===editing)||{date:day(anchor),time:'09:00',duration:50,patientId:selected||'',type:'Vestibular',status:'Agendado',value:0,paid:'Não',invoice:'Não',assessment:'',evolution:'',activities:''};const p=patient(s);const history=db.sessions.filter(x=>x.patientId===s.patientId&&x.id!==editing&&x.status==='Realizado').sort((a,b)=>(b.date+b.time).localeCompare(a.date+a.time));return `<div class="card"><h2>${editing?(view==='agenda'?'Agendamento':'Atendimento'):'Novo agendamento'}</h2>${editing&&!editable?'<p class="muted">Registro salvo · Somente leitura. Clique em Editar para alterar.</p>':''}${auditPanel(s)}${(view==='records'||view==='clinical')&&editing&&!editable?'<p class="muted">EXPORTAR gera um PDF com todos os atendimentos realizados deste paciente, organizados por data.</p>':''}${view==='agenda'&&s.status==='Agendado'?'<p class="muted">Clique em INICIAR para abrir a avaliação e evolução deste atendimento.</p>':''}<form id="sessionForm"><fieldset><div class="grid">${pSelect(s.patientId)}${field('Data','date',s.date,'date','required')}${field('Hora','time',s.time,'time','required')}${field('Duração (minutos)','duration',s.duration,'number','min="5" max="480" required')}<label>Tipo<select name="type">${options(['Vestibular','Ortopédico','Domiciliar'],s.type)}</select></label><label>Situação<select name="status">${options(['Agendado','Realizado','Cancelado','Faltou'],view==='clinical'&&editable&&s.status==='Agendado'?'Realizado':s.status)}</select></label>${field('Valor (R$)','value',s.value,'number','min="0" step="0.01" required')}<label>Pago<select name="paid">${options(['Não','Sim'],s.paid)}</select></label>${field('Data do pagamento','paymentDate',s.paymentDate||'','date')}<label>NFS-e emitida<select name="invoice">${options(['Não','Sim'],s.invoice)}</select></label></div>${(view==='records'||view==='clinical')?`<label>Anotações da avaliação — campo livre provisório<textarea name="assessment">${esc(s.assessment)}</textarea></label><label>Evolução do atendimento<textarea name="evolution">${esc(s.evolution)}</textarea></label><label>Atividades realizadas, dosagem e resposta<textarea name="activities">${esc(s.activities)}</textarea></label>`:''}${editing&&editable?reasonField(view==='clinical'&&s.status==='Agendado'?'Registro da avaliação e evolução do atendimento.':''):''}</fieldset><div class="row">${!editing||editable?`<button>Salvar atendimento</button>${editing?'<button type="button" class="secondary" data-action="cancelEdit">Cancelar edição</button>':''}`:'<button type="button" data-action="edit">Editar atendimento</button>'}${view==='agenda'&&editing&&!editable&&s.status==='Agendado'?'<button type="button" data-action="start">INICIAR</button>':''}<button type="button" class="secondary" data-action="close">Fechar</button>${(view==='records'||view==='clinical')&&editing&&!editable?'<button type="button" data-action="exportPDF">EXPORTAR</button>':''}${editing?`<button type="button" class="secondary" data-return="${s.patientId}">Agendar retorno</button><button type="button" class="secondary" data-patient="${s.patientId}">Abrir cadastro</button>`:''}</div></form>${(view==='records'||view==='clinical')?`<h3 style="margin-top:24px">Atendimentos anteriores ${p?'de '+esc(p.name):''}</h3>${history.length?history.map(h=>`<details><summary>${date(h.date)} · ${h.time} · ${money(h.value)} · ${h.paid==='Sim'?'Pago':'Pendente'}</summary><p><strong>Avaliação:</strong> ${esc(h.assessment)}</p><p style="white-space:pre-wrap"><strong>Evolução:</strong> ${esc(h.evolution)}</p><p style="white-space:pre-wrap"><strong>Atividades:</strong> ${esc(h.activities)}</p></details>`).join(''):'<p class="muted">Nenhum atendimento realizado registrado.</p>'}`:''}</div>`}
function patients(){const p=db.patients.find(x=>x.id===selected)||{};app.innerHTML=`<div class="card"><div class="row"><h2 style="flex:1">Pacientes</h2><button data-action="newPatient">+ Novo paciente</button></div><input id="search" placeholder="Buscar por nome"><div id="patientList">${patientRows(db.patients)}</div></div>${selected!==null?`<div class="card"><h2>${p.id?'Cadastro e histórico':'Novo paciente'}</h2><form id="patientForm"><div class="grid">${field('Nome','name',p.name,'text','required maxlength="150"')}${field('Telefone','phone',p.phone,'tel')}${field('CPF','cpf',p.cpf,'text','maxlength="14"')}${field('Nascimento','birth',p.birth,'date')}${field('Peso (kg)','weight',p.weight,'number','min="1" max="500" step="0.1"')}${field('Altura (cm)','height',p.height,'number','min="30" max="250" step="0.1"')}<label>Tipo de atendimento<select name="type">${options(['Vestibular','Ortopédico','Domiciliar'],p.type||'Vestibular')}</select></label></div>${field('Endereço / rua','address',p.address)}<div class="address-grid">${field('Número','number',p.number,'text','maxlength="20" placeholder="1624"')}${field('Bairro','neighborhood',p.neighborhood,'text','maxlength="100" placeholder="Champagnat"')}${field('Cidade','city',p.city,'text','maxlength="100" placeholder="Estância do Meio"')}${field('CEP','zip',p.zip,'text','inputmode="numeric" maxlength="9" pattern="[0-9]{5}-?[0-9]{3}" placeholder="99900-000"')}</div><button>Salvar cadastro</button></form>${p.id?`<h3 style="margin-top:24px">Atendimentos</h3><p>${db.sessions.filter(s=>s.patientId===p.id&&s.status==='Realizado').length} realizados · ${money(db.sessions.filter(s=>s.patientId===p.id&&s.status==='Realizado'&&s.paid==='Não').reduce((n,s)=>n+Number(s.value),0))} pendentes de sessões realizadas</p><button data-return="${p.id}">Agendar atendimento</button>${sessionRows(db.sessions.filter(s=>s.patientId===p.id))}`:''}</div>`:''}`;document.getElementById('search').oninput=e=>document.getElementById('patientList').innerHTML=patientRows(db.patients.filter(p=>p.name.toLocaleLowerCase().includes(e.target.value.toLocaleLowerCase())))}
function patientRows(rows){return rows.length?rows.map(p=>`<div class="patient-row"><button class="secondary" data-patient="${p.id}">${esc(p.name)}</button><span class="muted">${esc(p.type)} · ${esc(p.phone)}</span><button data-return="${p.id}" aria-label="Agendar para ${esc(p.name)}">AGENDAR</button></div>`).join(''):'<p class="muted">Nenhum paciente encontrado.</p>'}
function sessionRows(rows){return `<div class="scroll"><table><thead><tr><th>Data</th><th>Paciente</th><th>Situação</th><th>Valor</th><th>Pago</th><th>NFS-e</th><th></th></tr></thead><tbody>${[...rows].sort((a,b)=>(b.date+b.time).localeCompare(a.date+a.time)).map(s=>`<tr><td>${date(s.date)} ${s.time}</td><td>${esc(patient(s)?.name)}</td><td>${esc(s.status)}</td><td>${money(s.value)}</td><td>${s.paid}</td><td>${s.invoice}</td><td><button data-session="${s.id}">Abrir</button></td></tr>`).join('')}</tbody></table></div>`}
function finance(){const done=db.sessions.filter(s=>s.status==='Realizado');const received=db.sessions.filter(s=>s.paid==='Sim').reduce((n,s)=>n+Number(s.value),0);const pending=done.filter(s=>s.paid==='Não').reduce((n,s)=>n+Number(s.value),0);app.innerHTML=`<div class="grid"><div class="card">Recebimentos registrados — todos os períodos<div class="stats">${money(received)}</div></div><div class="card">A receber — sessões realizadas<div class="stats">${money(pending)}</div></div><div class="card">Atendimentos realizados<div class="stats">${done.length}</div></div></div><div class="card"><h2>Financeiro por atendimento</h2><p class="muted">Abra a sessão para registrar pagamento, data e emissão da nota. Emissão automática de NFS-e e controle de despesas ainda não implementados.</p>${sessionRows(db.sessions)}</div>${editing!==null?financialForm():''}`}
const sessionLabels={patientId:'Paciente',date:'Data',time:'Hora',duration:'Duração (minutos)',type:'Tipo',status:'Situação',value:'Valor',paid:'Pago',paymentDate:'Data do pagamento',invoice:'NFS-e emitida',assessment:'Avaliação',evolution:'Evolução',activities:'Atividades'};
function reasonField(defaultReason=''){return '<label>Motivo da edição (obrigatório)<textarea name="editReason" required maxlength="1000" placeholder="Descreva o que foi corrigido e por quê.">'+esc(defaultReason)+'</textarea></label>'}
function snapshot(s){const copy=structuredClone(s);delete copy.audit;return copy}
function versionDetails(s){return `<dl>${Object.entries(sessionLabels).filter(([key])=>(view==='records'||view==='clinical')||!['assessment','evolution','activities'].includes(key)).map(([key,label])=>{let value=s[key]??'';if(key==='patientId')value=db.patients.find(p=>p.id===value)?.name||value;if(key==='value')value=money(value);return `<dt><strong>${label}</strong></dt><dd style="white-space:pre-wrap;margin:3px 0 12px">${esc(value)}</dd>`}).join('')}</dl>`}
function auditPanel(s){if(!s.audit?.length)return '';const last=s.audit[s.audit.length-1];const stamp=t=>new Date(t).toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'medium'});return `<div class="audit-compact"><strong title="Horário no fuso deste dispositivo">Atendimento editado · ${esc(stamp(last.at))}</strong><p>Motivo: ${esc(last.reason)}</p><details><summary>Ver registro original e histórico (${s.audit.length})</summary><details><summary>Consultar registro original</summary>${versionDetails(s.audit[0].before)}</details>${[...s.audit].reverse().map(entry=>`<div class="audit-version"><strong>${esc(stamp(entry.at))}</strong><p>${esc(entry.reason)}</p><details><summary>Versão anterior a esta edição</summary>${versionDetails(entry.before)}</details></div>`).join('')}</details></div>`}
function updateSession(next,sessionId,changes,reason){const index=next.sessions.findIndex(s=>s.id===sessionId);const old=next.sessions[index];const before=snapshot(old);const after={...before,...changes};if(JSON.stringify(before)===JSON.stringify(after))return false;next.sessions[index]={...after,audit:[...(old.audit||[]),{at:new Date().toISOString(),reason,before}]};return true}
function financialForm(){const s=db.sessions.find(x=>x.id===editing);if(!s)return '';return `<div class="card"><h2>Pagamento · ${esc(patient(s)?.name)} · ${date(s.date)}</h2>${auditPanel(s)}<form id="financialForm"><fieldset ${editable?'':'disabled'}><div class="grid">${field('Valor (R$)','value',s.value,'number','min="0" step="0.01" required')}<label>Pago<select name="paid">${options(['Não','Sim'],s.paid)}</select></label>${field('Data do pagamento','paymentDate',s.paymentDate||'','date')}<label>NFS-e emitida<select name="invoice">${options(['Não','Sim'],s.invoice)}</select></label></div>${editable?reasonField():''}</fieldset><div class="row">${editable?'<button>Salvar pagamento</button><button type="button" class="secondary" data-action="cancelEdit">Cancelar edição</button>':'<button type="button" data-action="edit">Editar atendimento</button>'}<button type="button" class="secondary" data-action="close">Fechar</button></div></form></div>`}
function backup(){app.innerHTML=`<div class="card"><h2>Backup dos dados de teste</h2><p>O armazenamento desta versão depende deste navegador e do caminho do arquivo. Limpar os dados do Chrome, usar outro perfil ou mover o arquivo pode impedir o acesso aos registros. Exporte antes de atualizar.</p><button data-action="export">Exportar backup JSON</button><label style="margin-top:20px">Restaurar backup (substitui os dados atuais)<input id="import" type="file" accept=".json,application/json"></label></div><div class="card"><h2>Antes do uso com pacientes reais</h2><p>Esta versão serve para testar o fluxo. A próxima etapa requer banco de dados local, proteção de acesso, backup automático, proteção do histórico de alterações contra adulteração e validação das fichas clínicas.</p><h3>Google Agenda</h3><p>Não conectado. A futura integração dependerá da configuração da conta Google, autorização e regras de sincronização. Nenhum compromisso será enviado por este protótipo.</p><h3>Ficha vestibular</h3><p>Por enquanto há campos livres. Testes, critérios de interpretação e referências serão definidos juntos antes de incluir qualquer sugestão diagnóstica.</p></div>`}
function openDay(d){anchor=new Date(d+'T12:00:00');view='agenda';selected=null;editing='';editable=true;render()}
app.onkeydown=e=>{if(e.target.dataset.day&&(e.key==='Enter'||e.key===' ')){e.preventDefault();openDay(e.target.dataset.day)}};
app.onclick=e=>{const t=e.target.closest('button');if(!t){const slot=e.target.closest('[data-day]');if(slot)openDay(slot.dataset.day);return;}if(t.dataset.view){navigate(t.dataset.view);return}if(t.dataset.session){editing=t.dataset.session;editable=false;if(view==='patients')view='records';render();return}if(t.dataset.patient){view='patients';selected=t.dataset.patient;render();return}if(t.dataset.return){view='agenda';selected=t.dataset.return;editing='';editable=true;render();return}const a=t.dataset.action;if(a==='start'){const session=db.sessions.find(s=>s.id===editing);if(!session||session.status!=='Agendado')return;view='clinical';editable=true;render();return}if(a==='exportPDF'){try{const session=db.sessions.find(s=>s.id===editing);const p=patient(session);const rows=db.sessions.filter(s=>s.patientId===session.patientId&&s.status==='Realizado');const pdf=createPatientPDF(p,rows);pdf.save('atendimentos-'+p.name.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-zA-Z0-9]+/g,'-').slice(0,80)+'.pdf');say('PDF gerado com todos os atendimentos realizados deste paciente, por data.')}catch(error){say('Não foi possível gerar o PDF. Seus registros foram preservados.')}return}if(a==='edit'){editable=true;render()}if(a==='cancelEdit'){editable=false;if(view==='clinical')view='agenda';render()}if(a==='prev'||a==='next'){anchor.setDate(anchor.getDate()+(a==='prev'?-7:7));render()}if(a==='today'){anchor=new Date();render()}if(a==='new'){editing='';editable=true;selected=null;render()}if(a==='newPatient'){selected='';render()}if(a==='close'){editing=null;editable=false;if(view==='clinical')view='records';render()}if(a==='export'){const blob=new Blob([JSON.stringify(db,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download='fisio-backup-'+day(new Date())+'.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}};
app.onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));const editReason=String(data.editReason||'').trim();delete data.editReason;if(e.target.id==='patientForm'){if(data.zip){const digits=data.zip.replace(/\D/g,'');if(digits.length!==8)return say('Informe um CEP com oito dígitos.');data.zip=digits.slice(0,5)+'-'+digits.slice(5)}data.name=data.name.trim();if(!data.name)return say('Informe um nome.');data.id=selected||id();commit(next=>{const i=next.patients.findIndex(p=>p.id===data.id);if(i<0)next.patients.push(data);else next.patients[i]=data;selected=data.id})}if(e.target.id==='financialForm'){if(!editable)return;if(!editReason)return say('Informe o motivo da edição.');data.value=Number(data.value);if(!Number.isFinite(data.value)||data.value<0)return say('Valor inválido.');if(data.paid==='Sim'&&!data.paymentDate)return say('Informe a data do pagamento.');commit(next=>{updateSession(next,editing,data,editReason);editable=false});return}if(e.target.id==='sessionForm'){if(editing&&!editable)return;if(editing&&!editReason)return say('Informe o motivo da edição.');if(!db.patients.some(p=>p.id===data.patientId))return say('Cadastre e selecione um paciente.');data.value=Number(data.value);data.duration=Number(data.duration);if(!Number.isFinite(data.value)||data.value<0)return say('Valor inválido.');if(data.paid==='Sim'&&!data.paymentDate)return say('Informe a data do pagamento.');if((view==='records'||view==='clinical')&&data.status==='Realizado'&&!String(data.evolution||'').trim())return say('Registre a evolução para concluir o atendimento.');data.id=editing||id();const start=new Date(data.date+'T'+data.time).getTime();const clash=db.sessions.some(s=>s.id!==data.id&&s.status!=='Cancelado'&&s.status!=='Faltou'&&data.status!=='Cancelado'&&data.status!=='Faltou'&&start<new Date(s.date+'T'+s.time).getTime()+s.duration*60000&&start+data.duration*60000>new Date(s.date+'T'+s.time).getTime());if(clash&&!confirm('Existe sobreposição com um atendimento local. Salvar mesmo assim?'))return;commit(next=>{const i=next.sessions.findIndex(s=>s.id===data.id);if(i<0)next.sessions.push({assessment:'',evolution:'',activities:'',...data});else updateSession(next,data.id,data,editReason);editing=data.id;editable=false})}};
app.onchange=async e=>{if(e.target.id!=='import')return;try{const data=JSON.parse(await e.target.files[0].text());const ids=new Set();if(data.version!==1||!Array.isArray(data.patients)||!Array.isArray(data.sessions))throw Error();for(const p of data.patients){if(typeof p.id!=='string'||typeof p.name!=='string'||ids.has(p.id))throw Error();ids.add(p.id)}const sessionIds=new Set();for(const s of data.sessions){if(!ids.has(s.patientId)||typeof s.id!=='string'||sessionIds.has(s.id)||!/^\d{4}-\d{2}-\d{2}$/.test(s.date)||!/^\d{2}:\d{2}$/.test(s.time)||!['Agendado','Realizado','Cancelado','Faltou'].includes(s.status)||!['Sim','Não'].includes(s.paid)||!['Sim','Não'].includes(s.invoice)||typeof s.value!=='number'||!Number.isFinite(s.value)||s.value<0||typeof s.duration!=='number'||s.duration<5||s.duration>480)throw Error();if(s.audit!==undefined){if(!Array.isArray(s.audit))throw Error();for(const a of s.audit){if(typeof a.reason!=='string'||!a.reason.trim()||typeof a.at!=='string'||!Number.isFinite(Date.parse(a.at))||!a.before||typeof a.before!=='object'||Array.isArray(a.before)||a.before.id!==s.id)throw Error()}}sessionIds.add(s.id)}if(confirm('Substituir os dados atuais por este backup? Exporte os dados atuais primeiro se precisar mantê-los.'))if(persist(data)){say('Backup restaurado.');render()}}catch{say('Arquivo inválido. Os dados atuais foram preservados.')}};
render();
